select case when suppliers.rating >= 3.6 then 'high' when suppliers.rating >= 2.6 then 'mid' else 'low' end as rating_bucket, suppliers.country, count(distinct store_sales.units) as unique_products from store_sales inner join products on store_sales.product_id = products.id left join suppliers on products.supplier_id = suppliers.id group by case when suppliers.rating >= 3.6 then 'high' when suppliers.rating >= 2.6 then 'mid' else 'low' end, suppliers.country order by rating_bucket, country desc limit 5
